import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

// 간단한 인증 상태 관리 (실제로는 Provider/Riverpod 등 사용)
class AuthService extends ChangeNotifier {
  bool _isLoggedIn = false;
  bool _hasCompletedOnboarding = false;

  bool get isLoggedIn => _isLoggedIn;
  bool get hasCompletedOnboarding => _hasCompletedOnboarding;

  void login() {
    _isLoggedIn = true;
    notifyListeners();
  }

  void logout() {
    _isLoggedIn = false;
    notifyListeners();
  }

  void completeOnboarding() {
    _hasCompletedOnboarding = true;
    notifyListeners();
  }
}

// 전역 AuthService 인스턴스
final authService = AuthService();

// 인증 가드가 포함된 라우터
GoRouter createAuthRouter() {
  return GoRouter(
    initialLocation: '/',
    debugLogDiagnostics: true,

    // 인증 상태 변경 시 라우터 새로고침
    refreshListenable: authService,

    // 글로벌 리다이렉트
    redirect: (context, state) {
      final isLoggedIn = authService.isLoggedIn;
      final hasCompletedOnboarding = authService.hasCompletedOnboarding;
      final currentPath = state.uri.path;

      // 로그인 페이지에 있는 경우
      final isLoggingIn = currentPath == '/login';
      // 온보딩 페이지에 있는 경우
      final isOnboarding = currentPath == '/onboarding';

      // 1. 로그인하지 않은 경우 → 로그인 페이지로
      if (!isLoggedIn && !isLoggingIn) {
        return '/login';
      }

      // 2. 로그인했지만 온보딩 미완료 → 온보딩 페이지로
      if (isLoggedIn && !hasCompletedOnboarding && !isOnboarding) {
        return '/onboarding';
      }

      // 3. 로그인 상태에서 로그인/온보딩 페이지 접근 → 홈으로
      if (isLoggedIn && hasCompletedOnboarding && (isLoggingIn || isOnboarding)) {
        return '/';
      }

      // 리다이렉트 불필요
      return null;
    },

    routes: [
      // 로그인 페이지
      GoRoute(
        path: '/login',
        name: 'login',
        builder: (context, state) => const LoginPage(),
      ),

      // 온보딩 페이지
      GoRoute(
        path: '/onboarding',
        name: 'onboarding',
        builder: (context, state) => const OnboardingPage(),
      ),

      // 메인 앱 (인증 필요)
      GoRoute(
        path: '/',
        name: 'home',
        builder: (context, state) => const AuthenticatedHomePage(),
        routes: [
          GoRoute(
            path: 'profile',
            name: 'profile',
            builder: (context, state) => const ProfilePage(),
          ),
        ],
      ),
    ],

    errorBuilder: (context, state) => const NotFoundPage(),
  );
}

