import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

final GoRouter deepLinkRouter = GoRouter(
  initialLocation: '/',
  debugLogDiagnostics: true,

  routes: [
    GoRoute(
      path: '/',
      builder: (context, state) => const HomePage(),
    ),

    // 딥링크: yourapp://product/123 또는 https://yourapp.com/product/123
    GoRoute(
      path: '/product/:id',
      builder: (context, state) {
        final id = state.pathParameters['id']!;
        // 딥링크로 전달된 추가 데이터 확인
        final referrer = state.uri.queryParameters['ref'];
        return ProductPage(id: id, referrer: referrer);
      },
    ),

    // 딥링크: yourapp://share?code=ABC123
    GoRoute(
      path: '/share',
      builder: (context, state) {
        final code = state.uri.queryParameters['code'];
        return SharePage(code: code);
      },
    ),

    // 비밀번호 재설정 딥링크
    GoRoute(
      path: '/reset-password',
      builder: (context, state) {
        final token = state.uri.queryParameters['token'];
        if (token == null) {
          return const ErrorPage(message: '유효하지 않은 링크');
        }
        return ResetPasswordPage(token: token);
      },
    ),
  ],

  // 딥링크로 접근한 잘못된 경로 처리
  errorBuilder: (context, state) {
    return ErrorPage(message: '페이지를 찾을 수 없습니다: ${state.uri.path}');
  },
);

